Path('/runtime/http.php').write_text('<?php
function pandamonium_http_error() {
    http_response_code(503);
    header('Content-Type: application/json');
    echo json_encode(['error' => 'Myinstants media or provider request failed']);
    exit;
}
function pandamonium_fetch($url, $limit) {
    if (!str_starts_with($url, 'https://www.myinstants.com/')) pandamonium_http_error();
    if (preg_match('~^https://www.myinstants.com/en/(instant/[A-Za-z0-9_-]+|recent)$~', $url)) $url .= '/';
    $file = tempnam('/tmp', 'soundboard-');
    $command = ['/runtime/bin/curl', '--silent', '--show-error', '--proto', '=https',
        '--tlsv1.2', '--cacert', '/etc/ssl/cert.pem', '--connect-timeout', '5', '--max-time', '15',
        '--max-filesize', (string)$limit, '--output', $file, '--write-out', "%{http_code}\n%{content_type}",
        '--user-agent', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36', $url];
    $process = proc_open($command, [0 => ['file', '/dev/null', 'r'], 1 => ['pipe', 'w'], 2 => ['file', '/dev/null', 'w']], $pipes);
    if (!is_resource($process)) { unlink($file); pandamonium_http_error(); }
    $meta = stream_get_contents($pipes[1], 512);
    fclose($pipes[1]);
    $exit = proc_close($process);
    $body = file_get_contents($file, false, null, 0, $limit + 1);
    unlink($file);
    $parts = explode("\n", $meta, 2);
    if ($exit !== 0 || $parts[0] !== '200' || $body === false || strlen($body) > $limit) pandamonium_http_error();
    return [$body, strtolower(trim(explode(';', $parts[1] ?? '')[0]))];
}
')
Path('/runtime/soundboard-router.php').write_text("<?php
require '/runtime/http.php';
if (parse_url($_SERVER['REQUEST_URI'], PHP_URL_PATH) === '/soundboard-media') {
    $url = $_GET['url'] ?? '';
    if (!preg_match('#^https://www\.myinstants\.com/media/sounds/[A-Za-z0-9_.%~-]+\.(mp3|wav|ogg)$#', $url)
        || preg_match('/%2f|%5c/i', $url)) pandamonium_http_error();
    [$body, $type] = pandamonium_fetch($url, 8388608);
    if (!in_array($type, ['audio/mpeg', 'audio/mp3', 'audio/wav', 'audio/x-wav', 'audio/ogg'], true)) pandamonium_http_error();
    header('Content-Type: ' . $type);
    echo $body;
    return true;
}
require '/runtime/router.php';
